455	\begin{definition}[The combining map]
456		\label{def:combine-map}
457		\lean{MIPStarRE.QPBT.combinePoly, MIPStarRE.QPBT.combinePoly_eval}
458		\lean{MIPStarRE.QPBT.combinePoly_mem_polyFunc}
459		\lean{MIPStarRE.QPBT.combineLinePoly}
460		\lean{MIPStarRE.QPBT.combineLinePolynomial_natDegree_le}
461		\lean{MIPStarRE.QPBT.IsCombineLineCompatible, MIPStarRE.QPBT.combineLinePoly_spec}
462		\notready
463		\uses{def:polyfunc, def:line, def:ideg-deg-polynomials}
464		For $f, g \in \mathrm{ideg}_{d,m}(\F_q)$, the polynomial
465		$\mathrm{combine}_{f,g} \in \mathrm{ideg}_{d,2m+2}(\F_q)$ is defined by
466		\[
467			\mathrm{combine}_{f,g}(x, z, \alpha, \beta)
468			= \alpha f(x) + \beta g(z)\,,
469			\qquad x \in \F_q^m,\ z \in \F_q^m,\ \alpha \in \F_q,\
470			\beta \in \F_q\,.
471		\]
472		The combining map is also defined for polynomials restricted to lines.
473		Let $\ell$ be a line in $\F_q^{2m+2}$ with intercept
474		$u = (u_X, u_Z, u_\alpha, u_\beta)$ and slope
475		$v = (v_X, v_Z, v_\alpha, v_\beta)$, and let $\ell_X$ and $\ell_Z$ be
476		lines in $\F_q^m$ such that for every point
477		$(x, z, \alpha, \beta) \in \ell$ it holds that $x \in \ell_X$ and
478		$z \in \ell_Z$. Then for any two polynomials
479		$f \in \deg_{md}(\ell_X)$ and $g \in \deg_{md}(\ell_Z)$, the polynomial
480		$\mathrm{combine}_{f,g} \in \deg_{md+1}(\ell)$ is defined by
481		\begin{equation}
482			\label{eq:combine-lines}
483			\mathrm{combine}_{f,g}(u + t \cdot v)
484			= (u_\alpha + t \cdot v_\alpha)\, f(u_X + t \cdot v_X)
485			+ (u_\beta + t \cdot v_\beta)\, g(u_Z + t \cdot v_Z)\,,
486			\qquad t \in \F_q\,.
487		\end{equation}
488		The degree bound holds because $f$ and $g$, restricted to lines, are
489		polynomials of degree at most $md$ in the line parameter, and each is
490		multiplied by an affine factor of degree at most one.
491	\end{definition}
